1	// Base CSV parser interface and utilities for credit card and bank transaction parsing
2	
3	import type { ParsedTransaction, CSVParseResult } from '$lib/models/Transaction';
4	
5	/**
6	 * Base interface for all CSV parsers
7	 */
8	export interface ICSVParser {
9		/**
10		 * Parse a CSV string and return transactions
11		 * @param csvContent The raw CSV file content as a string
12		 * @returns CSVParseResult with parsed transactions and any errors
13		 */
14		parse(csvContent: string): CSVParseResult;
15	
16		/**
17		 * Validate if the CSV format matches this parser's expected format
18		 * @param csvContent The raw CSV file content as a string
19		 * @returns true if the format matches, false otherwise
20		 */
21		validateFormat(csvContent: string): boolean;
22	}
23	
24	/**
25	 * Resolved column layout for a parser.
26	 *
27	 * The Template Method only needs to know where the data rows start; each parser
28	 * extends this with whatever column indices its `parseRow` hook consumes.
29	 */
30	export interface CSVLayout {
31		/** First row index (0-based) that holds transaction data, not headers. */
32		dataStartIndex: number;
33	}
34	
35	/**
36	 * Base CSV parser with a shared `parse()` Template Method and common utilities.
37	 *
38	 * `parse()` owns the orchestration every bank parser used to duplicate:
39	 * strip BOM → `parseCSV` → empty-file guard → resolve the column layout →
40	 * loop the data rows → collect transactions and errors, all wrapped in a single
41	 * `try/catch`. Subclasses supply only what varies via two hooks:
42	 * `resolveLayout()` (header detection + column matching) and `parseRow()` (how a
43	 * single row maps to a `ParsedTransaction`). See RF-01 in the refactoring backlog.
44	 */
45	export abstract class BaseCSVParser<TLayout extends CSVLayout = CSVLayout> implements ICSVParser {
46		/**
47		 * Minimum number of rows required before parsing is attempted. Most banks ship
48		 * a header row plus data (2). TD Bank has no header row (1). Wealth Simple
49		 * treats a header-only file as an empty-but-valid result, so it disables the
50		 * guard (0).
51		 */
52		protected minimumRowCount = 2;
53	
54		/**
55		 * Per-bank sign convention (RF-11).
56		 *
57		 * The app convention is negative = expense, positive = refund/credit. Most
58		 * banks (PC Financial, EQ Bank, RBC, TD, Simplii) already export expenses as
59		 * negative, so the default is `false` (keep signs as-is). American Express
60		 * exports expenses as positive, so `AmexParser` overrides this to `true` and
61		 * `normalizeAmount` inverts the sign. Wealth Simple bypasses `normalizeAmount`
62		 * entirely and derives the sign from its `type` column.
63		 */
64		protected readonly expensesArePositive: boolean = false;
65	
66		/**
67		 * Template Method: the single, shared parse pipeline for every bank parser.
68		 */
69		parse(csvContent: string): CSVParseResult {
70			const transactions: ParsedTransaction[] = [];
71			const errors: string[] = [];
72	
73			try {
74				const rows = this.parseCSV(this.removeBOM(csvContent));
75	
76				if (rows.length < this.minimumRowCount) {
77					errors.push('CSV file is empty or has no data rows');
78					return { transactions, errors };
79				}
80	
81				// Hook: locate the header / column indices. On failure the subclass
82				// pushes its own format error and returns null.
83				const layout = this.resolveLayout(rows, errors, csvContent);
84				if (!layout) {
85					return { transactions, errors };
86				}
87	
88				// Hook: map each data row to a transaction (or null to skip / on error).
89				for (let i = layout.dataStartIndex; i < rows.length; i++) {
90					const transaction = this.parseRow(rows[i], layout, i, errors);
91					if (transaction) {
92						transactions.push(transaction);
93					}
94				}
95			} catch (e: unknown) {
96				errors.push(`Failed to parse CSV: ${e instanceof Error ? e.message : 'Unknown error'}`);
97			}
98	
99			return { transactions, errors };
100		}
101	
102		abstract validateFormat(csvContent: string): boolean;
103	
104		/**
105		 * Hook: detect the header and resolve the column indices this parser needs.
106		 *
107		 * Return the layout on success, or `null` after pushing a format/column error
108		 * onto `errors`. The original (pre-BOM-strip) `csvContent` is provided for
109		 * parsers whose `validateFormat` re-parses the raw string.
110		 */
111		protected abstract resolveLayout(
112			rows: string[][],
113			errors: string[],
114			csvContent: string
115		): TLayout | null;
116	
117		/**
118		 * Hook: map a single data row to a transaction.
119		 *
120		 * Return `null` to skip the row silently (incomplete/empty) or after pushing a
121		 * per-row error. `rowIndex` is 0-based; user-facing messages use `rowIndex + 1`.
122		 */
123		protected abstract parseRow(
124			row: string[],
125			layout: TLayout,
126			rowIndex: number,
127			errors: string[]
128		): ParsedTransaction | null;
129	
130		/**
131		 * Shared row finaliser for parsers whose amount lives in a single value.
132		 *
133		 * Validates the vendor name, applies the per-bank sign convention via
134		 * `normalizeAmount`, and returns the finished transaction. Consolidating the
135		 * `normalizeAmount` → assignment step here is what lets `amount` land as a
136		 * plain `number` (RF-01): callers have already rejected a null raw amount, and
137		 * the guard below narrows `normalizeAmount`'s `number | null` result.
138		 *
139		 * The per-bank sign convention comes from the `expensesArePositive` subclass
140		 * property, applied inside `normalizeAmount`.
141		 *
142		 * @param rawAmount - Parsed, non-null amount (caller reports invalid amounts).
143		 */
144		protected finalizeRow(
145			transactionDate: string,
146			vendorName: string,
147			rawAmount: number,
148			rowNumber: number,
149			errors: string[],
150			missingVendorMessage = 'Missing vendor name/description'
151		): ParsedTransaction | null {
152			if (!vendorName) {
153				errors.push(`Row ${rowNumber}: ${missingVendorMessage}`);
154				return null;
155			}
156	
157			const amount = this.normalizeAmount(rawAmount);
158			if (amount === null) return null;
159	
160			return { transaction_date: transactionDate, vendor_name: vendorName, amount };
161		}
162	
163		/**
164		 * Parse CSV string into rows and columns
165		 * Handles quoted fields with commas
166		 */
167		protected parseCSV(csvContent: string): string[][] {
168			const lines = csvContent.split(/\r?\n/);
169			const result: string[][] = [];
170	
171			// Strip a surviving surrounding "..." pair from a finalized field.
172			// EQ Bank exports double-encoded values like `"""-$33.00"""`, which the
173			// standard unwrap above reduces to `"-$33.00"` (literal " still present).
174			const stripOuterQuotes = (field: string): string => {
175				const trimmed = field.trim();
176				if (trimmed.length >= 2 && trimmed.startsWith('"') && trimmed.endsWith('"')) {
177					return trimmed.slice(1, -1).trim();
178				}
179				return trimmed;
180			};
181	
182			for (const line of lines) {
183				if (!line.trim()) continue;
184	
185				const row: string[] = [];
186				let currentField = '';
187				let inQuotes = false;
188	
189				for (let i = 0; i < line.length; i++) {
190					const char = line[i];
191	
192					if (char === '"') {
193						// Handle escaped quotes
194						if (inQuotes && line[i + 1] === '"') {
195							currentField += '"';
196							i++; // Skip next quote
197						} else {
198							inQuotes = !inQuotes;
199						}
200					} else if (char === ',' && !inQuotes) {
201						row.push(stripOuterQuotes(currentField));
202						currentField = '';
203					} else {
204						currentField += char;
205					}
206				}
207	
208				// Add the last field
209				row.push(stripOuterQuotes(currentField));
210				result.push(row);
211			}
212	
213			return result;
214		}
215	
216		/**
217		 * Parse a date string in MM/DD/YYYY or YYYY-MM-DD format to YYYY-MM-DD
218		 */
219		protected parseDate(dateStr: string): string | null {
220			try {
221				// Remove any leading/trailing whitespace
222				dateStr = dateStr.trim();
223	
224				// Try YYYY-MM-DD format (new EQ Bank format)
225				const ymdMatch = dateStr.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
226				if (ymdMatch) {
227					const [, year, month, day] = ymdMatch;
228					return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
229				}
230	
231				// Try MM/DD/YYYY format
232				const mdyMatch = dateStr.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
233				if (mdyMatch) {
234					const [, month, day, year] = mdyMatch;
235					return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
236				}
237	
238				// Try DD MMM YYYY format (e.g., "31 May 2025" or "31-May-25")
239				const dmmyMatch = dateStr.match(/^(\d{1,2})[\s-]([A-Za-z]{3})[.\s-]*(\d{2,4})$/);
240				if (dmmyMatch) {
241					const [, day, monthStr, year] = dmmyMatch;
242					const monthMap: Record<string, string> = {
243						jan: '01',
244						feb: '02',
245						mar: '03',
246						apr: '04',
247						may: '05',
248						jun: '06',
249						jul: '07',
250						aug: '08',
251						sep: '09',
252						oct: '10',
253						nov: '11',
254						dec: '12'
255					};
256					const month = monthMap[monthStr.toLowerCase()];
257					if (month) {
258						const fullYear = year.length === 2 ? `20${year}` : year;
259						return `${fullYear}-${month}-${day.padStart(2, '0')}`;
260					}
261				}
262	
263				// Try DD Mon YYYY format with full month name
264				const dmonyMatch = dateStr.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
265				if (dmonyMatch) {
266					const [, day, monthStr, year] = dmonyMatch;
267					const monthMap: Record<string, string> = {
268						january: '01',
269						february: '02',
270						march: '03',
271						april: '04',
272						may: '05',
273						june: '06',
274						july: '07',
275						august: '08',
276						september: '09',
277						october: '10',
278						november: '11',
279						december: '12'
280					};
281					const month = monthMap[monthStr.toLowerCase()];
282					if (month) {
283						return `${year}-${month}-${day.padStart(2, '0')}`;
284					}
285				}
286	
287				return null;
288			} catch {
289				return null;
290			}
291		}
292	
293		/**
294		 * Parse amount from string, handling currency symbols, commas, and parentheses for negatives
295		 */
296		protected parseAmount(amountStr: string): number | null {
297			try {
298				// Trim whitespace and any surrounding quote characters left over from
299				// double-encoded CSV exports (e.g. EQ Bank emits `"""-$33.00"""` which
300				// unwraps once to a value still containing literal " characters).
301				amountStr = amountStr
302					.trim()
303					.replace(/^["']+|["']+$/g, '')
304					.trim();
305	
306				// Check if amount is in parentheses (negative)
307				const isNegative = amountStr.startsWith('(') && amountStr.endsWith(')');
308				if (isNegative) {
309					amountStr = amountStr.slice(1, -1);
310				}
311	
312				// Remove currency symbols, commas, whitespace, and any embedded quotes
313				amountStr = amountStr.replace(/[$,\s"']/g, '');
314	
315				// Parse the number
316				const amount = parseFloat(amountStr);
317				if (isNaN(amount)) return null;
318	
319				return isNegative ? -Math.abs(amount) : amount;
320			} catch {
321				return null;
322			}
323		}
324	
325		/**
326		 * Remove BOM (Byte Order Mark) if present
327		 */
328		protected removeBOM(content: string): string {
329			if (content.charCodeAt(0) === 0xfeff) {
330				return content.slice(1);
331			}
332			return content;
333		}
334	
335		/**
336		 * Check if a header row contains expected columns (case-insensitive)
337		 */
338		protected hasExpectedColumns(header: string[], expectedColumns: string[]): boolean {
339			const headerLower = header.map((h) => h.toLowerCase().trim());
340			return expectedColumns.every((col) => headerLower.includes(col.toLowerCase()));
341		}
342	
343		/**
344		 * Normalizes transaction amounts to the app convention:
345		 * negative = expense, positive = refund/credit.
346		 *
347		 * The per-bank sign convention comes from the `expensesArePositive` subclass
348		 * property (RF-11):
349		 * - PC Financial, EQ Bank, RBC, TD Bank, Simplii already use negative for
350		 *   expenses → `expensesArePositive = false` (default), keep signs as-is
351		 * - American Express uses positive for expenses → `expensesArePositive = true`,
352		 *   invert the sign
353		 *
354		 * @param amount - The parsed amount from CSV
355		 * @returns Normalized amount (negative = expense, positive = refund/credit) or null if input is null
356		 *
357		 * @example
358		 * // PC Financial (expensesArePositive = false): -50.00 (expense) → keep as-is
359		 * normalizeAmount(-50.00) // Returns -50.00
360		 *
361		 * @example
362		 * // American Express (expensesArePositive = true): 50.00 (expense) → invert to -50.00
363		 * normalizeAmount(50.00) // Returns -50.00
364		 *
365		 * @example
366		 * // PC Financial (expensesArePositive = false): 25.00 (refund) → keep as-is
367		 * normalizeAmount(25.00) // Returns 25.00
368		 *
369		 * Specification: #{#trn1b}
370		 */
371		protected normalizeAmount(amount: number | null): number | null {
372			if (amount === null || amount === undefined) return null;
373			if (amount === 0) return 0;
374	
375			return this.expensesArePositive ? amount * -1 : amount;
376		}
377	}
