1	// Excel to CSV conversion utility - #{#xls1b}
2	// Converts XLS/XLSX files to CSV text for consumption by existing bank parsers
3	
4	import * as XLSX from 'xlsx';
5	
6	/**
7	 * Convert an Excel file (XLS or XLSX) to CSV text.
8	 * Reads the first sheet and outputs comma-separated values.
9	 *
10	 * @param buffer - The Excel file content as an ArrayBuffer
11	 * @returns CSV text string
12	 * @throws Error if the file is invalid or contains no sheets
13	 */
14	export function convertExcelToCSV(buffer: ArrayBuffer): string {
15		const workbook = XLSX.read(buffer, { type: 'array', cellDates: true, dateNF: 'yyyy-mm-dd' });
16		const firstSheetName = workbook.SheetNames[0];
17		if (!firstSheetName) {
18			throw new Error('Excel file contains no sheets');
19		}
20		const sheet = workbook.Sheets[firstSheetName];
21		return XLSX.utils.sheet_to_csv(sheet);
22	}
23	
24	/**
25	 * Detect whether a File is an Excel file based on extension or MIME type.
26	 *
27	 * @param file - The File object to check
28	 * @returns true if the file is XLS or XLSX
29	 */
30	export function isExcelFile(file: File): boolean {
31		const extension = file.name.toLowerCase().split('.').pop();
32		if (extension === 'xls' || extension === 'xlsx') return true;
33		if (
34			file.type === 'application/vnd.ms-excel' ||
35			file.type === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
36		)
37			return true;
38		return false;
39	}
