1	<script lang="ts">
2		import { onMount } from 'svelte';
3		import { SvelteSet } from 'svelte/reactivity';
4		import { page } from '$app/stores';
5		import { goto } from '$app/navigation';
6		import { resolve } from '$app/paths';
7		import { supabase } from '$lib/supabaseClient';
8		import { TransactionService } from '$lib/services/TransactionService';
9		import {
10			CREDIT_CARD_TYPES,
11			type CreditCardType,
12			type TransactionRow
13		} from '$lib/models/Transaction';
14		import {
15			readDateFilter,
16			applyDateFilterParams,
17			clearDateFilterParams
18		} from '$lib/utils/sharedDateFilter';
19		import {
20			matchesTransactionFilters,
21			hasActiveTransactionFilters
22		} from '$lib/utils/transactionFilters';
23		import { Datepicker } from 'flowbite-svelte';
24		import {
25			toDate,
26			toISODateString,
27			dateOrRangeToDate,
28			formatDate
29		} from '$lib/utils/dateConversion';
30		import FilterPanel from '$lib/components/FilterPanel.svelte';
31		import FilteredEmptyState from '$lib/components/FilteredEmptyState.svelte';
32		import DataTable from '$lib/components/DataTable.svelte';
33		import Notification from '$lib/components/Notification.svelte';
34		import { emptySelection } from '$lib/utils/selectionModel';
35	
36		const transactionService = new TransactionService(supabase);
37	
38		let allTransactions: TransactionRow[] = $state([]);
39		let familyId: string | null = $state(null);
40		let transactionSelection = $state(emptySelection());
41		let error: string | null = $state(null);
42		let importing = $state(false);
43		let selectedCardType: CreditCardType = $state('PC Financial');
44		let includeIgnored = $state(false);
45		let editRow: TransactionRow | null = $state(null);
46		let deleting = new SvelteSet<string>();
47		let bulkDeleting = $state(false);
48		let successMessage: string | null = $state(null);
49	
50		// #{#sdf2c} Read date filters from URL query parameters
51		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
52		let urlDateFrom = $derived(urlDateFilter.dateFrom);
53		let urlDateTo = $derived(urlDateFilter.dateTo);
54	
55		// Client-side filters - temporary values for inputs.
56		// Seed from the URL params directly (not from the urlDate* deriveds) so the
57		// initializer doesn't capture a reactive value; the $effect below keeps them
58		// in sync when the URL changes.
59		let tempFilterDateFrom = $state(readDateFilter($page.url.searchParams).dateFrom);
60		let tempFilterDateTo = $state(readDateFilter($page.url.searchParams).dateTo);
61		let tempFilterVendor = $state('');
62		let tempFilterAmountMin = $state('');
63		let tempFilterAmountMax = $state('');
64		let tempFilterCreditCardType: CreditCardType | 'all' = $state('all'); // #{#tcf1a}
65	
66		// Sync temp date values when URL changes
67		$effect(() => {
68			tempFilterDateFrom = urlDateFrom;
69			tempFilterDateTo = urlDateTo;
70		});
71	
72		// Active filter values used for filtering (non-date filters only)
73		let filterVendor = $state('');
74		let filterAmountMin = $state('');
75		let filterAmountMax = $state('');
76		let filterCreditCardType: CreditCardType | 'all' = $state('all'); // #{#tcf1a}
77	
78		async function loadTransactions(): Promise<void> {
79			if (!familyId) return;
80			error = null;
81			try {
82				// DataTable sorts client-side over the full in-memory list; load in a stable order.
83				// Card/bank type is filtered client-side via the Filters panel, so the query
84				// only needs the excluded-rows toggle.
85				allTransactions = await transactionService.list(familyId, {
86					sort: 'transaction_date',
87					direction: 'desc',
88					includeExcluded: includeIgnored
89				});
90			} catch (e) {
91				error = e instanceof Error ? e.message : 'Failed to load transactions';
92			}
93		}
94	
95		async function getDefaultFamily(): Promise<string | null> {
96			const { data: familyMembers } = await supabase
97				.from('family_members')
98				.select('family_id, is_default')
99				.eq('user_id', (await supabase.auth.getUser()).data.user?.id)
100				.order('is_default', { ascending: false })
101				.limit(1);
102	
103			return familyMembers?.[0]?.family_id || null;
104		}
105	
106		onMount(async () => {
107			familyId = await getDefaultFamily();
108			if (familyId) {
109				await loadTransactions();
110			} else {
111				error = 'No family found. Please create or join a family first.';
112			}
113		});
114	
115		async function onFileSelected(e: Event): Promise<void> {
116			const input = e.target as HTMLInputElement;
117			const file = input.files?.[0];
118			if (!file || !familyId) return;
119	
120			importing = true;
121			error = null;
122			successMessage = null;
123	
124			try {
125				const result = await transactionService.importFromCSV(familyId, file, selectedCardType);
126	
127				if (result.errors.length > 0) {
128					error = result.errors.join('\n');
129				}
130	
131				if (result.imported > 0 || result.skipped > 0) {
132					// #{#tid3a} Import summary UX
133					if (result.imported === 0 && result.skipped > 0) {
134						successMessage = `No new transactions — ${result.skipped} already in your records`;
135					} else if (result.skipped > 0) {
136						successMessage = `Imported ${result.imported} transaction${result.imported === 1 ? '' : 's'}, skipped ${result.skipped} duplicate${result.skipped === 1 ? '' : 's'}`;
137					} else {
138						successMessage = `Imported ${result.imported} transaction${result.imported === 1 ? '' : 's'}`;
139					}
140					await loadTransactions();
141				}
142			} catch (e) {
143				error = e instanceof Error ? e.message : 'Failed to import transactions';
144			} finally {
145				importing = false;
146				input.value = '';
147			}
148		}
149	
150		async function deleteTransaction(t: TransactionRow): Promise<void> {
151			if (!confirm('Delete this transaction?')) return;
152			deleting.add(t.id);
153			error = null;
154			try {
155				await transactionService.delete(t.id);
156				allTransactions = allTransactions.filter((x) => x.id !== t.id);
157				successMessage = 'Transaction deleted';
158			} catch (e) {
159				error = e instanceof Error ? e.message : 'Failed to delete transaction';
160			} finally {
161				deleting.delete(t.id);
162			}
163		}
164	
165		// #{#tbd1a} Selection-based bulk delete — only the checked rows.
166		async function deleteSelected(): Promise<void> {
167			const ids = Array.from(transactionSelection.selected);
168			if (ids.length === 0) return;
169			if (!confirm(`Delete ${ids.length} selected transaction${ids.length === 1 ? '' : 's'}?`)) {
170				return;
171			}
172	
173			bulkDeleting = true;
174			error = null;
175			const original = [...allTransactions];
176			// Optimistic update — remove from UI immediately
177			allTransactions = allTransactions.filter((t) => !transactionSelection.selected.has(t.id));
178	
179			try {
180				await transactionService.deleteByIds(ids);
181				successMessage = `${ids.length} transaction${ids.length === 1 ? '' : 's'} deleted`;
182				transactionSelection = emptySelection();
183			} catch (e) {
184				// Rollback on failure
185				allTransactions = original;
186				error = e instanceof Error ? e.message : 'Failed to delete transactions';
187			} finally {
188				bulkDeleting = false;
189			}
190		}
191	
192		async function toggleExcluded(t: TransactionRow): Promise<void> {
193			error = null;
194			try {
195				const updated = await transactionService.toggleExcluded(t.id, !t.excluded);
196				allTransactions = allTransactions.map((x) => (x.id === updated.id ? updated : x));
197				successMessage = updated.excluded ? 'Transaction excluded' : 'Transaction included';
198			} catch (e) {
199				error = e instanceof Error ? e.message : 'Failed to update transaction';
200			}
201		}
202	
203		async function saveEdit(): Promise<void> {
204			if (!editRow) return;
205			error = null;
206			try {
207				const updated = await transactionService.update(editRow.id, {
208					vendor_name: editRow.vendor_name,
209					amount: editRow.amount,
210					transaction_date: editRow.transaction_date,
211					credit_card_type: editRow.credit_card_type
212				});
213				allTransactions = allTransactions.map((t) => (t.id === updated.id ? updated : t));
214				editRow = null;
215				successMessage = 'Transaction updated';
216			} catch (e) {
217				error = e instanceof Error ? e.message : 'Failed to save transaction';
218			}
219		}
