221		function formatAmount(amount: number): string {
222			const abs = Math.abs(amount);
223			const formatted = abs.toFixed(2);
224			return amount < 0 ? `-$${formatted}` : `$${formatted}`;
225		}
226	
227		function getAmountClass(amount: number): string {
228			return amount < 0 ? 'text-red-600' : 'text-green-600';
229		}
