1	// PC Financial Credit Card CSV Parser
2	// Expected format: Description,Type,Card Holder Name,Date,Time,Amount
3	// Date format: MM/DD/YYYY
4	// Amount: negative for purchases, positive for refunds
5	
6	import { BaseCSVParser } from './BaseCSVParser';
7	import type { CSVLayout } from './BaseCSVParser';
8	import type { ParsedTransaction } from '$lib/models/Transaction';
9	
10	interface PCFinancialLayout extends CSVLayout {
11		descriptionIdx: number;
12		dateIdx: number;
13		amountIdx: number;
14	}
15	
16	export class PCFinancialParser extends BaseCSVParser<PCFinancialLayout> {
17		protected resolveLayout(
18			rows: string[][],
19			errors: string[],
20			csvContent: string
21		): PCFinancialLayout | null {
22			const header = rows[0];
23			if (!this.validateFormat(csvContent)) {
24				errors.push(
25					'Invalid PC Financial CSV format. Expected columns: Description, Type, Card Holder Name, Date, Time, Amount'
26				);
27				return null;
28			}
29	
30			// Find column indices
31			const descriptionIdx = header.findIndex((h) => h.toLowerCase().includes('description'));
32			const dateIdx = header.findIndex((h) => h.toLowerCase() === 'date');
33			const amountIdx = header.findIndex((h) => h.toLowerCase() === 'amount');
34	
35			return { dataStartIndex: 1, descriptionIdx, dateIdx, amountIdx };
36		}
37	
38		protected parseRow(
39			row: string[],
40			layout: PCFinancialLayout,
41			rowIndex: number,
42			errors: string[]
43		): ParsedTransaction | null {
44			if (row.length < 6) return null; // Skip incomplete rows
45	
46			const description = row[layout.descriptionIdx]?.trim();
47			const dateStr = row[layout.dateIdx]?.trim();
48			const amountStr = row[layout.amountIdx]?.trim();
49	
50			// Parse date
51			const transaction_date = this.parseDate(dateStr);
52			if (!transaction_date) {
53				errors.push(`Row ${rowIndex + 1}: Invalid date format "${dateStr}"`);
54				return null;
55			}
56	
57			// Parse amount
58			const rawAmount = this.parseAmount(amountStr);
59			if (rawAmount === null) {
60				errors.push(`Row ${rowIndex + 1}: Invalid amount "${amountStr}"`);
61				return null;
62			}
63	
64			// PC Financial uses negative for expenses — keep as-is (default expensesArePositive) (#{#trn2a})
65			return this.finalizeRow(transaction_date, description, rawAmount, rowIndex + 1, errors);
66		}
67	
68		validateFormat(csvContent: string): boolean {
69			try {
70				csvContent = this.removeBOM(csvContent);
71				const rows = this.parseCSV(csvContent);
72				if (rows.length === 0) return false;
73	
74				const header = rows[0];
75				const expectedColumns = ['description', 'type', 'card holder name', 'date', 'time', 'amount'];
76				return this.hasExpectedColumns(header, expectedColumns);
77			} catch {
78				return false;
79			}
80		}
81	}
