1	/**
2	 * resolveCategory
3	 *
4	 * Single shared way to answer "which Category does this row belong to?"
5	 * (RF-09 — replaces three divergent implementations: the expenses page's
6	 * inline Category rebuild, its `categories.find(...)` lookup, and the
7	 * receipts/reconciliation pages' hand-rolled categoryMap loops.)
8	 *
9	 * Rows carry denormalized category fields (`category_id` / `category_name` /
10	 * `category_color`) produced by ExpenseService. Resolution prefers the
11	 * authoritative entry in the loaded `categories` list, falling back to the
12	 * row's denormalized fields when the list has no match (e.g. category loaded
13	 * on the row before the categories list refreshed).
14	 */
15	
16	import type { Category } from '$lib/types/Category';
17	
18	/** Minimal row shape: anything carrying a denormalized category reference. */
19	export interface CategoryRowRef {
20		category_id?: string | null;
21		category_name?: string | null;
22		category_color?: string | null;
23	}
24	
25	/**
26	 * Resolve a row's Category, or null when the row is uncategorized.
27	 */
28	export function resolveCategory(row: CategoryRowRef, categories: Category[]): Category | null {
29		if (!row.category_id) return null;
30	
31		const match = categories.find((c) => c.id === row.category_id);
32		if (match) return match;
33	
34		if (!row.category_name) return null;
35	
36		return {
37			id: row.category_id,
38			name: row.category_name,
39			color: row.category_color ?? null
40		};
41	}
42	
43	/**
44	 * Look up a Category directly by its id, or undefined when the list has no match.
45	 *
46	 * This is the by-id counterpart to {@link resolveCategory}: use it when you already
47	 * hold a bare category id (a selection, a rule's target) rather than a row with
48	 * denormalized fields — it does a plain lookup with no fallback synthesis.
49	 */
50	export function findCategoryById(categories: Category[], categoryId: string): Category | undefined {
51		return categories.find((c) => c.id === categoryId);
52	}
53	
54	/**
55	 * Build a receipt-id → Category map for pages that render many rows
56	 * (receipts / reconciliation). Uncategorized rows map to null.
57	 */
58	export function buildCategoryMap<Row extends CategoryRowRef & { receipt_id: string }>(
59		rows: Row[],
60		categories: Category[]
61	): Record<string, Category | null> {
62		const map: Record<string, Category | null> = {};
63		for (const row of rows) {
64			map[row.receipt_id] = resolveCategory(row, categories);
65		}
66		return map;
67	}
